package com.bank.qa.contractmicro;

import java.util.*;

// PROVIDER: deployed independently; a new version may change the response.
class AccountsService {
    private final int version;
    AccountsService(int version) { this.version = version; }

    Map<String, Object> balance(String acct) {
        Map<String, Object> r = new LinkedHashMap<>();
        r.put("accountId", acct);
        if (version >= 2) r.put("availableBalance", 950000.00); // BREAKING: renamed field
        else r.put("balance", 950000.00);                       // v1: field transfers relies on
        return r;
    }
    int version() { return version; }
}
