package com.bank.qa.contractmicro;

import java.util.*;
import java.util.logging.Logger;

// CONSUMER (transfers svc) expectation + the can-i-deploy gate.
class TransfersContract {
    private static final Logger log = Logger.getLogger(TransfersContract.class.getName());
    private final Set<String> requiredFields = Set.of("accountId", "balance");

    // Verify a provider version satisfies what transfers depends on.
    boolean isSatisfiedBy(Map<String, Object> providerResponse) {
        for (String f : requiredFields)
            if (!providerResponse.containsKey(f)) {
                log.severe("Contract break: transfers needs '" + f + "' but provider omitted it");
                return false;
            }
        return true;
    }

    // CI gate: may this provider version deploy without breaking transfers?
    boolean canIDeploy(AccountsService provider) {
        boolean ok = isSatisfiedBy(provider.balance("SAV2001"));
        log.info("can-i-deploy AccountsService v" + provider.version()
            + " -> " + (ok ? "YES (transfers safe)" : "NO (blocked before prod)"));
        return ok;
    }
}
