package com.bank.qa.contractmicro;

import java.util.logging.*;

public class MicroContractDemo {
    private static final Logger log = Logger.getLogger(MicroContractDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new McLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        TransfersContract transfers = new TransfersContract();

        log.info("=== Accounts v1 (compatible) tries to deploy ===");
        transfers.canIDeploy(new AccountsService(1));   // YES

        log.info("=== Accounts v2 (renamed balance field) tries to deploy ===");
        boolean v2 = transfers.canIDeploy(new AccountsService(2));  // NO — caught in CI
        log.info(v2 ? "deployed" : "DEPLOY BLOCKED: fix provider or coordinate change "
            + "(expand-and-contract) BEFORE production — no outage");
    }
}

